let self = $.GetContextPanel();
let diffList = null;

(function () {
    diffList = self.FindChildTraverse("DifficultyList");

    //$.Msg("Difficulty Select Register");
    GameEvents.Subscribe("showDifficultySelect", ShowDifficultySelect);
    CustomNetTables.SubscribeNetTableListener("account", OnAccountData);
})();

function ShowDifficultySelect() {
    self.RemoveClass("Hidden");
    const data = CustomNetTables.GetTableValue("account", "difficulty_unlock");
    //$.Msg("ShowDifficultySelect", data);
    UpdateDifficultyButtons(data);
}

/// 监听服务器给的存档
function OnAccountData(table, key, data) {
    if (key !== "difficulty_unlock") return;
    UpdateDifficultyButtons(data);
}

function UpdateDifficultyButtons(data) {
    diffList.RemoveAndDeleteChildren();

    let unlocked = (data && data.level) || 1;

    // n1 ~ n10 （示例）
    for (let i = 1; i <= 10; i++) {
        let p = $.CreatePanel("Button", diffList, "diff" + i);
        p.AddClass("DifficultyButton");

        if (i > unlocked) p.AddClass("Locked");

        let label = $.CreatePanel("Label", p, "");
        label.text = "N" + i;

        if (i <= unlocked) {
            p.SetPanelEvent("onactivate", ((level) => () => SelectDifficulty(level))(i));
        }
    }
}

function SelectDifficulty(level) {
    // 通知服务器开始游戏
    GameEvents.SendCustomGameEventToServer("select_difficulty", { level: level });

    // 关闭 UI
    self.AddClass("Hidden");
}

