+
+        var found = ctx.FindChildTraverse("GameFlowRoot");
+        if (found) return found;
+
+        var parent = ctx.GetParent();
+        while (parent) {
+            if (parent.id === "GameFlowRoot") return parent;
+            found = parent.FindChildTraverse("GameFlowRoot");
+            if (found) return found;
+            parent = parent.GetParent();
+        }
+
+        return null;
+    }
+
+    function CachePanels() {
+        if (!state.root) {
+            state.root = ResolveRootPanel();
+        }
+        if (!state.root) return false;
+
+        if (!state.start) {
+            state.start = state.root.FindChildTraverse("StartGameRoot");
+        }
+        if (!state.difficulty) {
+            state.difficulty = state.root.FindChildTraverse("DifficultyRoot");
+        }
+        if (!state.end) {
